# ═══════════════════════════════════════════════════════════════════════════════
#  DETECCIÓN DE HARDWARE Y DISCOS
# ═══════════════════════════════════════════════════════════════════════════════

def _ejecutar(cmd: list[str], timeout: int = 30) -> tuple[int, str, str]:
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return r.returncode, r.stdout.strip(), r.stderr.strip()
    except FileNotFoundError:
        return -1, "", f"No encontrado: {cmd[0]}"
    except subprocess.TimeoutExpired:
        return -2, "", "Timeout"
    except Exception as e:
        return -3, "", str(e)


def detectar_disco_arranque() -> str:
    rc, out, _ = _ejecutar(["findmnt", "-n", "-o", "SOURCE", "/"])
    if rc == 0 and out:
        dev = out.strip()
        # Si es un device mapper (LVM/LUKS), intentar resolver el disco físico subyacente
        if dev.startswith("/dev/mapper/") or dev.startswith("/dev/dm-"):
            rc2, out2, _ = _ejecutar(["lsblk", "-no", "PKNAME", dev])
            if rc2 == 0 and out2.strip():
                return out2.strip().split()[0]
        dev = dev.removeprefix("/dev/")
        return re.sub(r'p?\d+$', '', dev)
    rc, out, _ = _ejecutar(["lsblk", "-J", "-o", "NAME,MOUNTPOINTS"])
    if rc == 0 and out:
        try:
            for disco in json.loads(out).get("blockdevices", []):
                if _disco_tiene_mount(disco, "/"):
                    return disco["name"]
        except json.JSONDecodeError as e:
            # lsblk devolvió JSON malformado; se usa /proc/mounts como fallback
            print(f"[WARN] listar_disco_arranque: lsblk JSON inválido: {e}", file=sys.stderr)
    try:
        with open("/proc/mounts") as f:
            for linea in f:
                partes = linea.split()
                if len(partes) >= 2 and partes[1] == "/":
                    src = partes[0]
                    if src.startswith("/dev/mapper/") or src.startswith("/dev/dm-"):
                        rc2, out2, _ = _ejecutar(["lsblk", "-no", "PKNAME", src])
                        if rc2 == 0 and out2.strip():
                            return out2.strip().split()[0]
                    return re.sub(r'p?\d+$', '', src.removeprefix("/dev/"))
    except OSError:
        pass
    return ""


def _disco_tiene_mount(nodo: dict, punto: str) -> bool:
    mps = nodo.get("mountpoints") or [nodo.get("mountpoint")]
    if punto in (mps or []):
        return True
    for hijo in nodo.get("children", []):
        if _disco_tiene_mount(hijo, punto):
            return True
    return False


def listar_discos() -> list[dict]:
    rc, out, _ = _ejecutar([
        "lsblk", "-J", "-b", "-o", "NAME,SIZE,TYPE,MOUNTPOINTS,MODEL,TRAN,ROTA,VENDOR"
    ])
    if rc != 0 or not out:
        return []
    try:
        datos = json.loads(out)
    except json.JSONDecodeError:
        return []
    disco_arranque = detectar_disco_arranque()
    discos = []
    for nodo in datos.get("blockdevices", []):
        if nodo.get("type") != "disk":
            continue
        nombre = nodo.get("name", "")
        size_b = int(nodo.get("size") or 0)
        model  = (nodo.get("model") or nodo.get("vendor") or "").strip()
        tran   = (nodo.get("tran") or "").strip()
        rota   = nodo.get("rota") in ("1", True, 1)
        parts  = []
        for hijo in nodo.get("children", []):
            if hijo.get("type") in ("part", "lvm"):
                mps = hijo.get("mountpoints") or [hijo.get("mountpoint")]
                parts.append({
                    "name":   hijo.get("name", ""),
                    "size_b": int(hijo.get("size") or 0),
                    "mounts": [m for m in mps if m],
                })
        discos.append({
            "name":        nombre,
            "size_b":      size_b,
            "size_human":  _bytes_a_human(size_b),
            "model":       model or "Disco desconocido",
            "tran":        tran.upper() if tran else "—",
            "tipo":        "HDD" if rota else "SSD/NVMe",
            "es_arranque": (nombre == disco_arranque),
            "particiones": parts,
            "montajes":    _montes_activos(nodo),
        })
    return discos


def _montes_activos(nodo: dict) -> list[str]:
    result = []
    mps = nodo.get("mountpoints") or [nodo.get("mountpoint")]
    result.extend([m for m in (mps or []) if m])
    for hijo in nodo.get("children", []):
        result.extend(_montes_activos(hijo))
    return result


def _bytes_a_human(b: int) -> str:
    fb = float(b)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if fb < 1024.0:
            return f"{fb:.1f} {unit}"
        fb /= 1024.0
    return f"{fb:.1f} PB"


def es_uefi() -> bool:
    return Path("/sys/firmware/efi").exists()


def detectar_microcode() -> str:
    try:
        with open("/proc/cpuinfo") as f:
            c = f.read().lower()
        if "genuineintel" in c or "intel" in c:
            return "intel-ucode"
        if "authenticamd" in c or "amd" in c:
            return "amd-ucode"
    except OSError:
        pass
    return ""  # fallback seguro: no instalar microcode incorrecto si no se detecta CPU


def verificar_internet() -> bool:
    # BUG-010 FIX: probar IPv4 primero; si no hay, intentar IPv6.
    # Sistemas con solo IPv6 (frecuente en redes modernas) fallarían con solo 8.8.8.8.
    rc4, _, _ = _ejecutar(["ping", "-c", "1", "-W", "3", "8.8.8.8"], timeout=6)
    if rc4 == 0:
        return True
    rc6, _, _ = _ejecutar(["ping6", "-c", "1", "-W", "3", "2001:4860:4860::8888"], timeout=6)
    return rc6 == 0


def verificar_herramientas() -> dict[str, bool]:
    tools = ["parted", "mkfs.fat", "mkfs.ext4", "arch-chroot",
             "pacstrap", "genfstab", "mount", "umount"]
    return {h: shutil.which(h) is not None for h in tools}


# ═══════════════════════════════════════════════════════════════════════════════
#  DETECCIÓN INTELIGENTE DE HARDWARE (CPU arch level + GPU)
# ═══════════════════════════════════════════════════════════════════════════════

def detectar_cpu_arch_level() -> str:
    """Detecta el nivel de arquitectura x86: v2, v3, v4."""
    try:
        with open("/proc/cpuinfo") as f:
            flags = ""
            for line in f:
                if line.startswith("flags"):
                    flags = line.split(":", 1)[1].lower()
                    break
        flag_set = set(flags.split())
        v4 = {"avx512f", "avx512bw", "avx512cd", "avx512dq", "avx512vl"}
        v3 = {"avx", "avx2", "bmi1", "bmi2", "f16c", "fma", "movbe", "xsave"}
        if v4.issubset(flag_set):
            return "x86-64-v4"
        elif v3.issubset(flag_set):
            return "x86-64-v3"
        else:
            return "x86-64-v2"
    except Exception:
        return "x86-64"


def detectar_gpu() -> dict:
    """Detecta el vendor de GPU via /proc o lspci. Devuelve vendor + pkgs recomendados."""
    try:
        rc, out, _ = _ejecutar(["lspci", "-mm"])
        if rc == 0 and out:
            amd_kw = ["advanced micro devices", "amd/ati", "radeon", "navi",
                      "polaris", "vega", "rdna", "gfx"]
            intel_kw = ["intel corporation", "intel xe", "iris xe",
                        "uhd graphics", "hd graphics"]
            for line in out.splitlines():
                line_lower = line.lower()
                if "vga" in line_lower or "display" in line_lower or "3d controller" in line_lower:
                    if any(k in line_lower for k in amd_kw):
                        return {"vendor": "amd", "model": _parse_lspci_model(line),
                                "pkgs": DRIVER_PKGS_AMD}
                    if any(k in line_lower for k in intel_kw):
                        return {"vendor": "intel", "model": _parse_lspci_model(line),
                                "pkgs": DRIVER_PKGS_INTEL}
    except Exception as e:
        print(f"[WARN] detectar_gpu lspci: {e}")

    # Fallback: /sys/class/drm
    try:
        for vendor_file in Path("/sys/class/drm").glob("card*/device/vendor"):
            vid = vendor_file.read_text().strip()
            if vid == "0x1002":   # AMD
                return {"vendor": "amd", "model": "AMD GPU", "pkgs": DRIVER_PKGS_AMD}
            if vid == "0x8086":   # Intel
                return {"vendor": "intel", "model": "Intel GPU", "pkgs": DRIVER_PKGS_INTEL}
    except Exception as e:
        print(f"[WARN] detectar_gpu /sys/class/drm: {e}")

    return {"vendor": "amd", "model": "GPU desconocida (asumiendo AMD)", "pkgs": DRIVER_PKGS_AMD}


def _parse_lspci_model(line: str) -> str:
    """Extrae el nombre del modelo de una línea de lspci -mm."""
    parts = [p.strip('"') for p in line.split('"') if p.strip('"')]
    return parts[5] if len(parts) > 5 else parts[-1] if parts else "Desconocido"


def detectar_tipo_disco_destino(dev_name: str) -> str:
    """Detecta si el disco es HDD, SSD o NVMe para el IO scheduler."""
    rota_path = Path(f"/sys/block/{dev_name}/queue/rotational")
    try:
        rota = rota_path.read_text().strip()
        if "nvme" in dev_name or "mmcblk" in dev_name:
            return "nvme"
        return "hdd" if rota == "1" else "ssd"
    except Exception:
        return "ssd"


