# ═══════════════════════════════════════════════════════════════════════════════
#  API — Python ↔ pywebview bridge
# ═══════════════════════════════════════════════════════════════════════════════

class InstaladorAPI:
    """Métodos expuestos al JavaScript."""

    def __init__(self, ventana: "VentanaInstalador"):
        self._v = ventana

    def set_language(self, code: str) -> bool:
        """Llamado desde JS al elegir idioma. Guarda el código para
        usarlo al generar archivos de configuración (fastfetch, etc.)."""
        allowed = ("en", "es", "zh")
        if code in allowed:
            self._v._lang = code
            return True
        return False

    def on_ready(self):
        """DOM listo: poblar discos y mostrar bienvenida."""
        discos = listar_discos()
        self._v._jsc("pyRenderDiscos", json.dumps(discos))
        return True

    def iniciar_instalacion(self, username: str, password: str, hostname: str,
                             timezone: str, disco: str, bootloader: str, usb: bool,
                             locale: str = "", keymap: str = ""):
        """El usuario pulsó 'Instalar AvalOS' con configuración válida."""
        _username = username.strip()
        if not _username:
            # Guard Python-side: el JS ya valida, pero por si acaso
            return False
        self._v._username = _username
        self._v._password = password
        self._v._hostname = hostname.strip() or DEFAULT_HOSTNAME
        self._v._timezone = timezone or DEFAULT_TIMEZONE
        # Validar locale: debe estar en la lista o usar el default
        _valid_locales = {lc for lc, _ in LOCALES}
        self._v._locale  = locale if locale in _valid_locales else DEFAULT_LOCALE
        # Validar keymap: debe estar en la lista o usar el default
        _valid_keymaps = {km for km, _ in KEYMAPS}
        self._v._keymap  = keymap if keymap in _valid_keymaps else DEFAULT_KEYMAP
        self._v._disco_destino = disco
        self._v._bootloader = bootloader if bootloader in ('grub','sd-boot','refind','none') else 'grub'
        self._v._modo_usb  = bool(usb)
        self._v._config_lista.set()
        return True

    def abortar_instalacion(self):
        self._v._abortado = True
        return True

    def reintentar(self):
        # Lock para evitar race condition TOCTOU entre check y start del hilo
        with self._v._lock:
            if self._v._instalando:
                return True   # ya corre, ignorar
            self._v._abortado = False
            self._v._instalando = True   # reservar antes de soltar el lock
        t = threading.Thread(target=self._v._run_instalacion, daemon=True)
        t.start()
        return True

    def reiniciar_equipo(self):
        try:
            subprocess.Popen(["systemctl", "reboot"])
        except Exception as e:
            self._v._log(f"[WARN] reboot: {e}", "warn")
        return True

    def cerrar(self):
        if self._v.window:
            try:
                self._v.window.destroy()
            except Exception:
                pass
        return True


# ═══════════════════════════════════════════════════════════════════════════════
#  VENTANA + LÓGICA DE INSTALACIÓN
# ═══════════════════════════════════════════════════════════════════════════════

class VentanaInstalador:

    def __init__(self):
        self.window: "webview.Window | None" = None
        self._cerrado    = False
        self._abortado   = False
        self._instalando     = False
        self._thread_started  = False   # guard anti double-fire
        # Configuración del wizard (se puebla en iniciar_instalacion)
        self._lang       = "en"   # elegido en la pantalla de idioma
        self._username   = ""
        self._password   = ""
        self._hostname   = DEFAULT_HOSTNAME
        self._timezone   = DEFAULT_TIMEZONE
        self._locale     = DEFAULT_LOCALE
        self._keymap     = DEFAULT_KEYMAP
        self._disco_destino: str | None = None
        self._bootloader = 'grub'  # 'grub' | 'sd-boot' | 'refind' | 'none'
        self._modo_usb   = False
        self._config_lista = threading.Event()
        self._lock         = threading.Lock()   # protege _instalando en reintentar()

    # ── JS helpers ────────────────────────────────────────────────────────────

    def _js(self, code: str):
        if self.window and not self._cerrado:
            try:
                self.window.evaluate_js(code)
            except Exception as e:
                print(f"[JS] {e}")

    def _jsc(self, func: str, *args):
        encoded = ", ".join(json.dumps(a, ensure_ascii=False) for a in args)
        self._js(f"{func}({encoded})")

    def _log(self, txt: str, cls: str = "info"):    self._jsc("pyLog", txt, cls)
    def _step(self, id_: str, st: str, det: str = ""): self._jsc("pyStep", id_, st, det)
    def _progress(self, pct: int):                  self._jsc("pyProgress", pct)
    def _info(self, id_: str, v: str, c: str = ""): self._jsc("pyInfo", id_, v, c)
    def _status(self, msg: str):                    self._jsc("pyStatus", msg)
    def _label(self, txt: str):                     self._jsc("pyStatusLabel", txt)

    def _on_close(self):
        self._cerrado  = True
        self._abortado = True
        self._config_lista.set()

    # ── Subprocess con streaming ──────────────────────────────────────────────

    def _run_cmd(self, cmd: list[str], timeout: int = 300,
                 log_cls: str = "info") -> tuple[int, str]:
        self._log(f"$ {' '.join(cmd)}", "cmd")
        salida: list[str] = []
        proc: "subprocess.Popen[str] | None" = None
        _timed_out = False

        def _kill_on_timeout():
            nonlocal _timed_out
            _timed_out = True
            if proc is not None:
                try:
                    proc.kill()
                except Exception:
                    pass

        try:
            proc = subprocess.Popen(cmd, stdout=subprocess.PIPE,
                                    stderr=subprocess.STDOUT, text=True, bufsize=1)
            if proc.stdout is None:
                return -1, "No stdout"

            timer = threading.Timer(timeout, _kill_on_timeout)
            timer.start()
            try:
                for linea in proc.stdout:
                    linea = linea.rstrip('\n')
                    if linea:
                        self._log(linea, log_cls)
                        salida.append(linea)
                    if self._abortado:
                        proc.kill()
                        proc.wait()
                        return -99, "\n".join(salida)
                proc.wait(timeout=5)
            finally:
                timer.cancel()

            if _timed_out:
                self._log(f"[TIMEOUT] {timeout}s — proceso terminado", "err")
                return -2, "\n".join(salida)

            return proc.returncode, "\n".join(salida)
        except Exception as e:
            self._log(f"[EXCEPCIÓN] {e}", "err")
            if proc is not None:
                try:
                    proc.kill(); proc.wait()
                except Exception:
                    pass
            return -3, ""

    def _run_chroot(self, cmd: list[str], timeout: int = 300) -> tuple[int, str]:
        return self._run_cmd(["arch-chroot", str(MOUNT_ROOT)] + cmd, timeout=timeout)

    def _run_chroot_stdin(self, stdin_data: str, cmd: list[str], timeout: int = 60) -> tuple[int, str]:
        """Ejecuta un comando en chroot pasando datos sensibles por stdin (ej: chpasswd)."""
        full_cmd = ["arch-chroot", str(MOUNT_ROOT)] + cmd
        try:
            proc = subprocess.run(
                full_cmd,
                input=stdin_data,
                capture_output=True,
                text=True,
                timeout=timeout,
            )
            out = (proc.stdout or "") + (proc.stderr or "")
            return proc.returncode, out.strip()
        except subprocess.TimeoutExpired:
            self._log(f"[TIMEOUT] {timeout}s en {cmd[0]}", "err")
            return -2, ""
        except Exception as e:
            self._log(f"[EXCEPCIÓN] {e}", "err")
            return -3, ""

    def _limpiar_montajes(self):
        self._log("\n── Limpiando montajes ──", "warn")
        puntos = [
            str(MOUNT_EFI),
            str(MOUNT_ROOT / "boot"),
            str(MOUNT_ROOT / "proc"),
            str(MOUNT_ROOT / "sys" / "firmware" / "efi" / "efivars"),
            str(MOUNT_ROOT / "sys"),
            str(MOUNT_ROOT / "dev" / "pts"),
            str(MOUNT_ROOT / "dev"),
            str(MOUNT_ROOT / "run"),
            str(MOUNT_ROOT),
            str(MOUNT_ISO),
        ]
        for p in puntos:
            if Path(p).is_mount():
                rc, _ = self._run_cmd(["umount", "-l", p])
                if rc == 0:
                    self._log(f"  desmontado: {p}", "ok")

    # ── Utilidades de escritura de archivos ───────────────────────────────────

    def _escribir(self, ruta_relativa: str, contenido: str):
        dest = MOUNT_ROOT / ruta_relativa.lstrip("/")
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(contenido, encoding="utf-8")
        self._log(f"  [escrito] /{ruta_relativa}", "ok")

    def _chown_r(self, ruta: str, usuario: str):
        self._run_chroot(["chown", "-R", f"{usuario}:{usuario}", ruta])

    # ═════════════════════════════════════════════════════════════════════════
    #  OPTIMIZACIONES DEL SISTEMA (ZRAM, oomd, BBR, IO scheduler, sysctl)
    # ═════════════════════════════════════════════════════════════════════════

    def _configurar_optimizaciones(self, gpu_info: dict, cpu_arch: str, disco_tipo: str):
        """Configura ZRAM+zstd, systemd-oomd, BBR, IO scheduler, sysctl y binarios de sistema."""

        self._log("\n── Optimizaciones del sistema ──\n", "step")

        # ── avalos-gpu-env: detecta GPU y escribe gpu-env.conf para Hyprland ──
        # El servicio avalos-gpu-detect.service (creado en _run_instalacion) llama
        # a este binario antes de que SDDM arranque, resolviendo la condición de
        # carrera con el `source` de hyprland.conf.
        _bin_dir = MOUNT_ROOT / "usr/local/bin"
        _bin_dir.mkdir(parents=True, exist_ok=True)
        _gpu_env_bin = _bin_dir / "avalos-gpu-env"
        _gpu_env_bin.write_text(
            "#!/bin/bash\n"
            "# AvalOS: detecta GPU y escribe gpu-env.conf para Hyprland\n"
            "# BUG FIX: los servicios systemd corren como root, $HOME apunta a /root,\n"
            "# no al home del usuario. Se usa /etc/hypr/gpu-env.conf como ruta fija;\n"
            "# hyprland.conf hace source desde ahí para la detección dinámica de GPU.\n"
            "HYPR_CFG=\"/etc/hypr/gpu-env.conf\"\n"
            "mkdir -p \"$(dirname \"$HYPR_CFG\")\"\n\n"
            "if lspci 2>/dev/null | grep -qiE 'amd|radeon|amdgpu'; then\n"
            "    cat > \"$HYPR_CFG\" << 'EOF'\n"
            "env = AMD_VULKAN_ICD,RADV\n"
            "env = VDPAU_DRIVER,radeonsi\n"
            "env = LIBVA_DRIVER_NAME,radeonsi\n"
            "EOF\n"
            "elif lspci 2>/dev/null | grep -qiE 'intel.*(graphics|vga|display)'; then\n"
            "    cat > \"$HYPR_CFG\" << 'EOF'\n"
            "env = LIBVA_DRIVER_NAME,iHD\n"
            "env = VDPAU_DRIVER,va_gl\n"
            "EOF\n"
            "else\n"
            "    # Fallback: archivo vacío (mesa auto-detecta)\n"
            "    : > \"$HYPR_CFG\"\n"
            "fi\n"
        )
        _gpu_env_bin.chmod(0o755)
        self._log("  /usr/local/bin/avalos-gpu-env instalado (chmod 755)", "ok")

        # Crear gpu-env.conf vacío por defecto (se sobreescribe por el servicio)
        # BUG-005 FIX: gpu_info no tiene '_usuario'; usar self._username (usuario real).
        # Sin este fix la ruta era "…/home//.config/…" (doble barra, directorio inexistente).
        try:
            if self._username:
                _default_cfg = MOUNT_ROOT / f"home/{self._username}" / ".config/hypr/gpu-env.conf"
                _default_cfg.parent.mkdir(parents=True, exist_ok=True)
                if not _default_cfg.exists():
                    _default_cfg.touch()
        except Exception as e:
            self._log(f"[WARN] config de archivos: {e}", "warn")

        # ── ZRAM con zstd ─────────────────────────────────────────────────────
        zram_path = MOUNT_ROOT / "etc" / "systemd" / "zram-generator.conf"
        zram_path.parent.mkdir(parents=True, exist_ok=True)
        zram_path.write_text(
            "[zram0]\n"
            "# ZRAM: swap comprimido en RAM — AvalOS\n"
            "# Limita a min(RAM_total/2, 8GB) — estándar zram-generator\n"
            "zram-size = min(ram / 2, 8192)\n"
            "compression-algorithm = zstd\n"
            "swap-priority = 100\n"
        )
        self._log("  ZRAM: zstd comprimido, max 8 GB, prioridad 100", "ok")

        # ── systemd-oomd ──────────────────────────────────────────────────────
        oomd_conf = MOUNT_ROOT / "etc" / "systemd" / "oomd.conf"
        oomd_conf.write_text(
            "[OOM]\n"
            "# Mata procesos cuando la presión de swap supera el 85%\n"
            "SwapUsedLimit=85%\n"
            "# o cuando la presión de memoria supera el 70% por más de 10s\n"
            "DefaultMemoryPressureLimit=70%\n"
            "DefaultMemoryPressureDurationSec=10s\n"
        )
        self._run_chroot(["systemctl", "enable", "systemd-oomd"])
        self._log("  systemd-oomd: habilitado (swap >85% → kill)", "ok")

        # ── sysctl conservador (sin flags peligrosos) ──────────────────────────
        sysctl_dir = MOUNT_ROOT / "etc" / "sysctl.d"
        sysctl_dir.mkdir(parents=True, exist_ok=True)

        # Memoria — ajustes medidos, no placebo
        (sysctl_dir / "80-avalos-memory.conf").write_text(
            "# AvalOS: memory tuning (conservador, medido)\n"
            "# Reduce agresividad de swap (ZRAM lo maneja)\n"
            "vm.swappiness = 10\n"
            "# Cache de VFS: más agresivo en retener inodos/dentries\n"
            "vm.vfs_cache_pressure = 50\n"
            "# Dirty pages: escribir antes de que sea urgente\n"
            "vm.dirty_ratio = 10\n"
            "vm.dirty_background_ratio = 5\n"
            "# Tiempo máximo de dirty pages antes de flush\n"
            "vm.dirty_expire_centisecs = 3000\n"
            "vm.dirty_writeback_centisecs = 500\n"
        )
        self._log("  sysctl memoria: swappiness=10, dirty_ratio=10", "ok")

        # Red: BBR + FQ
        (sysctl_dir / "81-avalos-bbr.conf").write_text(
            "# AvalOS: BBR congestion control (mainline desde Linux 4.9, muy estable)\n"
            "# FQ como qdisc (requerido por BBR)\n"
            "net.core.default_qdisc = fq\n"
            "# BBR: mejor throughput y latencia que CUBIC\n"
            "net.ipv4.tcp_congestion_control = bbr\n"
            "# Buffers de red razonables\n"
            "net.core.rmem_max = 16777216\n"
            "net.core.wmem_max = 16777216\n"
            "net.ipv4.tcp_rmem = 4096 87380 16777216\n"
            "net.ipv4.tcp_wmem = 4096 65536 16777216\n"
        )
        self._log("  BBR: net.ipv4.tcp_congestion_control=bbr + fq", "ok")

        # Seguridad mínima sin overhead
        (sysctl_dir / "82-avalos-security.conf").write_text(
            "# AvalOS: seguridad mínima razonable\n"
            "kernel.dmesg_restrict = 1\n"
            "kernel.kptr_restrict = 1\n"
            "net.ipv4.conf.default.rp_filter = 1\n"
            "net.ipv4.conf.all.rp_filter = 1\n"
        )
        self._log("  sysctl seguridad: dmesg_restrict=1, kptr_restrict=1", "ok")

        # ── IO scheduler por tipo de disco (udev) ──────────────────────────────
        udev_dir = MOUNT_ROOT / "etc" / "udev" / "rules.d"
        udev_dir.mkdir(parents=True, exist_ok=True)
        (udev_dir / "60-avalos-iosched.rules").write_text(
            '# AvalOS: IO scheduler automático por tipo de disco\n'
            '# HDD → bfq  (justo, buena latencia interactiva)\n'
            'ACTION=="add|change", KERNEL=="sd[a-z]*", '
            'ATTR{queue/rotational}=="1", ATTR{queue/scheduler}="bfq"\n'
            '# SSD SATA → mq-deadline  (simple, baja latencia)\n'
            'ACTION=="add|change", KERNEL=="sd[a-z]*", '
            'ATTR{queue/rotational}=="0", ATTR{queue/scheduler}="mq-deadline"\n'
            '# NVMe → kyber  (diseñado para baja latencia NVMe)\n'
            'ACTION=="add|change", KERNEL=="nvme[0-9n]*", '
            'ATTR{queue/scheduler}="kyber"\n'
            '# eMMC → mq-deadline\n'
            'ACTION=="add|change", KERNEL=="mmcblk[0-9]*", '
            'ATTR{queue/scheduler}="mq-deadline"\n'
        )
        self._log(f"  IO scheduler: bfq(HDD) / mq-deadline(SSD) / kyber(NVMe) — disco: {disco_tipo}", "ok")

        # ── DNS-over-TLS con systemd-resolved ─────────────────────────────────
        resolved_conf = MOUNT_ROOT / "etc" / "systemd" / "resolved.conf"
        resolved_conf.write_text(
            "[Resolve]\n"
            "# AvalOS: DNS-over-TLS con Cloudflare + Google\n"
            "DNS=1.1.1.1#cloudflare-dns.com 1.0.0.1#cloudflare-dns.com "
            "8.8.8.8#dns.google 8.8.4.4#dns.google\n"
            "FallbackDNS=9.9.9.9#dns.quad9.net\n"
            "DNSOverTLS=yes\n"
            "DNSSEC=allow-downgrade\n"
            "Cache=yes\n"
            "DNSStubListener=yes\n"
        )
        # Symlink para que NetworkManager use systemd-resolved
        try:
            (MOUNT_ROOT / "etc" / "resolv.conf").unlink(missing_ok=True)
            (MOUNT_ROOT / "etc" / "resolv.conf").symlink_to(
                "../run/systemd/resolve/stub-resolv.conf"
            )
        except OSError as e:
            # No es fatal, pero sin este symlink el DNS no funcionará post-install
            self._log(f"[WARN] resolv.conf symlink falló: {e}", "warn")
        self._run_chroot(["systemctl", "enable", "systemd-resolved"])
        self._log("  DNS-over-TLS: systemd-resolved (Cloudflare + Google + Quad9)", "ok")

        # ── Info del hardware detectado ────────────────────────────────────────
        self._log(
            f"  CPU arch: {cpu_arch}  |  GPU: {gpu_info['vendor'].upper()} "
            f"({gpu_info['model']})  |  Disco: {disco_tipo.upper()}",
            "ok"
        )

    # ═════════════════════════════════════════════════════════════════════════
    #  CONFIGURAR HYPRLAND + ENTORNO WAYLAND
    # ═════════════════════════════════════════════════════════════════════════

    def _configurar_hyprland(self, usuario: str, gpu_info: dict):
        home = f"home/{usuario}"

        # Wayland env vars (GPU-specific se generan según hardware detectado)
        _gpu_vendor = gpu_info.get("vendor", "amd")
        if _gpu_vendor == "intel":
            _gpu_env = "LIBVA_DRIVER_NAME=iHD\nVDPAU_DRIVER=va_gl\n"
        else:  # amd (default)
            _gpu_env = "VDPAU_DRIVER=radeonsi\nLIBVA_DRIVER_NAME=radeonsi\n"

        self._escribir("etc/environment", f"""\
QT_QPA_PLATFORM=wayland:xcb
QT_AUTO_SCREEN_SCALE_FACTOR=1
QT_WAYLAND_DISABLE_WINDOWDECORATION=1
GDK_BACKEND=wayland,x11
SDL_VIDEODRIVER=wayland
CLUTTER_BACKEND=wayland
MOZ_ENABLE_WAYLAND=1
ELECTRON_OZONE_PLATFORM_HINT=auto
XDG_SESSION_TYPE=wayland
XDG_SESSION_DESKTOP=Hyprland
XDG_CURRENT_DESKTOP=Hyprland
{_gpu_env}__GLX_VENDOR_LIBRARY_NAME=mesa
""")

        # os-release / lsb-release
        self._escribir("etc/os-release", f"""\
NAME="AvalOS"
PRETTY_NAME="AvalOS"
ID=avalos
ID_LIKE=arch
BUILD_ID=rolling
ANSI_COLOR="38;2;122;162;247"
HOME_URL="https://github.com/{AVALOS_REPO}"
DOCUMENTATION_URL="https://wiki.archlinux.org"
LOGO=avalos-logo
""")
        self._escribir("etc/lsb-release", """\
LSB_VERSION=1.4
DISTRIB_ID=AvalOS
DISTRIB_RELEASE=rolling
DISTRIB_CODENAME=avalos
DISTRIB_DESCRIPTION="AvalOS"
""")

        # Repo AvalOS en pacman.conf
        avalos_repo = (
            "\n[avalos]\n"
            "SigLevel = Optional TrustAll\n"
            f"Server = {AVALOS_REPO_URL}\n"
        )
        # Multilib (necesario para Steam y libs 32-bit de juegos)
        multilib_repo = "\n[multilib]\nInclude = /etc/pacman.d/mirrorlist\n"

        pac_path = MOUNT_ROOT / "etc" / "pacman.conf"
        try:
            import re as _re
            existing = pac_path.read_text(encoding="utf-8") if pac_path.exists() else ""
            to_append = ""
            if "[avalos]" not in existing:
                to_append += avalos_repo
            if "[multilib]" not in existing:
                # Descomentar el bloque multilib con regex (tolerante a variaciones de espacio)
                existing_new = _re.sub(
                    r'#\s*\[multilib\]\s*\n#\s*Include\s*=\s*/etc/pacman\.d/mirrorlist',
                    "[multilib]\nInclude = /etc/pacman.d/mirrorlist",
                    existing
                )
                if "[multilib]" not in existing_new:
                    # No encontrado ni comentado — añadir al final
                    to_append += multilib_repo
                else:
                    existing = existing_new
            if to_append:
                pac_path.write_text(existing + to_append, encoding="utf-8")
            self._log("  repos [avalos] + [multilib] → pacman.conf", "ok")
        except OSError as e:
            self._log(f"[WARN] pacman.conf: {e}", "warn")

        # hyprland.conf — leído desde /usr/share/avalos/configs/
        _gpu_env_amd  = "env = AMD_VULKAN_ICD,RADV\nenv = VDPAU_DRIVER,radeonsi\nenv = LIBVA_DRIVER_NAME,radeonsi"
        _gpu_env_intel = "env = LIBVA_DRIVER_NAME,iHD\nenv = VDPAU_DRIVER,va_gl"
        _gpu_env_str  = _gpu_env_amd if _gpu_vendor == "amd" else _gpu_env_intel

        _hypr_tmpl = _leer_config("hyprland/hyprland.conf.template")
        if _hypr_tmpl:
            self._escribir(f"{home}/.config/hypr/hyprland.conf",
                           _hypr_tmpl.replace("%%GPU_ENV%%", _gpu_env_str).replace("%%KEYMAP%%", self._keymap))
        else:
            self._log("[WARN] hyprland.conf.template no encontrado — usando config embebida", "warn")

        # hyprpaper.conf
        _contenido = _leer_config("hyprland/hyprpaper.conf")
        if _contenido:
            self._escribir(f"{home}/.config/hypr/hyprpaper.conf", _contenido)
        else:
            self._escribir(f"{home}/.config/hypr/hyprpaper.conf",
                           "preload = ~/.config/hypr/wallpaper.png\nwallpaper = ,~/.config/hypr/wallpaper.png\nsplash = false\n")
        # Wallpaper PNG Tokyo Night (#1a1b26) sin dependencias externas
        try:
            import struct as _struct, zlib as _zlib
            def _make_chunk(tag, data):
                crc = _zlib.crc32(tag + data) & 0xffffffff
                return _struct.pack('>I', len(data)) + tag + data + _struct.pack('>I', crc)
            _w, _h, _R, _G, _B = 1920, 1080, 26, 27, 38
            _rows = (b'\x00' + bytes([_R, _G, _B]) * _w) * _h
            _png = (
                b'\x89PNG\r\n\x1a\n'
                + _make_chunk(b'IHDR', _struct.pack('>IIBBBBB', _w, _h, 8, 2, 0, 0, 0))
                + _make_chunk(b'IDAT', _zlib.compress(_rows, 9))
                + _make_chunk(b'IEND', b'')
            )
            wp_path = MOUNT_ROOT / f"{home}/.config/hypr/wallpaper.png"
            wp_path.write_bytes(_png)
            self._log("  wallpaper.png generado (Tokyo Night #1a1b26)", "ok")
        except Exception as _e:
            self._log(f"  [WARN] wallpaper: {_e}", "warn")

        # hypridle.conf
        _contenido = _leer_config("hyprland/hypridle.conf")
        if _contenido:
            self._escribir(f"{home}/.config/hypr/hypridle.conf", _contenido)
        else:
            self._escribir(f"{home}/.config/hypr/hypridle.conf", """\
general {
    lock_cmd = pidof hyprlock || hyprlock
    before_sleep_cmd = loginctl lock-session
    after_sleep_cmd = hyprctl dispatch dpms on
}
listener { timeout = 300;  on-timeout = hyprctl dispatch dpms off; on-resume = hyprctl dispatch dpms on; }
listener { timeout = 600;  on-timeout = loginctl lock-session; }
listener { timeout = 1800; on-timeout = systemctl suspend; }
""")

        # hyprlock.conf
        _contenido = _leer_config("hyprland/hyprlock.conf")
        if _contenido:
            self._escribir(f"{home}/.config/hypr/hyprlock.conf", _contenido)
        else:
            self._escribir(f"{home}/.config/hypr/hyprlock.conf", """\
background {
    monitor =
    path = ~/.config/hypr/wallpaper.png
    blur_size = 5; blur_passes = 3; brightness = 0.65
}
input-field {
    monitor =
    size = 300, 50
    outline_thickness = 2
    outer_color = rgb(7aa2f7); inner_color = rgb(1a1b26)
    font_color = rgb(7aa2f7)
    placeholder_text = <span foreground="#565f89">Password…</span>
    position = 0, -80; halign = center; valign = center
}
label {
    monitor =
    text = cmd[update:1000] date +"%H:%M"
    color = rgba(187, 154, 247, 1.0)
    font_size = 70; font_family = JetBrainsMono Nerd Font
    position = 0, 150; halign = center; valign = center
}
label {
    monitor =
    text = cmd[update:60000] date '+%A, %d de %B'
    color = rgba(122, 162, 247, 0.8)
    font_size = 18; font_family = JetBrainsMono Nerd Font
    position = 0, 70; halign = center; valign = center
}
""")

        # Waybar config
        _contenido = _leer_config("waybar/config.jsonc")
        if _contenido:
            self._escribir(f"{home}/.config/waybar/config.jsonc", _contenido)
        else:
            self._escribir(f"{home}/.config/waybar/config.jsonc", """\
{
  "layer": "top", "position": "top", "height": 30, "spacing": 4,
  "modules-left":   ["hyprland/workspaces", "hyprland/window"],
  "modules-center": ["clock"],
  "modules-right":  ["pulseaudio","network","battery","cpu","memory","temperature","tray","custom/powermenu"],
  "hyprland/workspaces": {
    "format": "{icon}",
    "format-icons": {"1":"①","2":"②","3":"③","4":"④","5":"⑤","6":"⑥","7":"⑦","8":"⑧","9":"⑨","active":"","default":""},
    "persistent-workspaces": {"*": 5}
  },
  "hyprland/window": {"max-length": 50, "separate-outputs": true},
  "clock": {"format": "{:%H:%M  %a %d/%m/%Y}", "tooltip-format": "<big>{:%Y %B}</big>\n<tt><small>{calendar}</small></tt>"},
  "cpu": {"format": "󰻠 {usage}%", "interval": 2},
  "memory": {"format": "󰍛 {}%", "interval": 5},
  "temperature": {"critical-threshold": 80, "format": "{icon} {temperatureC}°C", "format-icons": ["","",""]},
  "battery": {"states": {"warning":30,"critical":15}, "format": "{icon} {capacity}%", "format-charging": "󰂄 {capacity}%", "format-icons": ["󰁺","󰁻","󰁼","󰁽","󰁾","󰁿","󰂀","󰂁","󰂂","󰁹"]},
  "network": {"format-wifi":"󰤨 {signalStrength}%","format-ethernet":"󰈀 {ipaddr}","format-disconnected":"󰤭 Sin red"},
  "pulseaudio": {"format":"{icon} {volume}%","format-muted":"󰝟","format-icons":{"default":["󰕿","󰖀","󰕾"]},"on-click":"pavucontrol"},
  "tray": {"spacing": 8},
  "custom/powermenu": {"format":"","tooltip":false,"on-click":"~/.config/rofi/scripts/powermenu.sh"}
}
""")

        # Waybar style — Tokyo Night
        _contenido = _leer_config("waybar/style.css")
        if _contenido:
            self._escribir(f"{home}/.config/waybar/style.css", _contenido)
        else:
            self._escribir(f"{home}/.config/waybar/style.css", """\
* { font-family: "JetBrainsMono Nerd Font", monospace; font-size: 13px; border: none; border-radius: 0; min-height: 0; }
window#waybar { background-color: rgba(26,27,38,0.92); border-bottom: 2px solid rgba(122,162,247,.4); color: #c0caf5; }
.modules-left, .modules-center, .modules-right { padding: 0 6px; }
#workspaces button { color: #414868; padding: 0 4px; background: transparent; transition: color 0.15s; }
#workspaces button:hover, #workspaces button.active { color: #7aa2f7; background: rgba(122,162,247,.18); border-radius: 4px; }
#workspaces button.urgent { color: #f7768e; }
#window { color: #565f89; }
#clock { color: #bb9af7; font-weight: 700; }
#cpu { color: #7dcfff; } #memory { color: #9ece6a; }
#temperature { color: #c0caf5; } #temperature.critical { color: #f7768e; }
#battery { color: #c0caf5; } #battery.warning { color: #e0af68; } #battery.critical { color: #f7768e; }
#battery.charging { color: #9ece6a; }
#network { color: #7dcfff; } #network.disconnected { color: #f7768e; }
#pulseaudio { color: #c0caf5; } #pulseaudio.muted { color: #414868; }
#tray { padding: 0 4px; }
#custom-powermenu { color: #f7768e; padding: 0 8px; font-size: 16px; }
tooltip { background: rgba(26,27,38,.95); border: 1px solid rgba(122,162,247,.3); color: #c0caf5; font-size: 11px; border-radius: 4px; }
""")

        # mako (reemplaza dunst — BUG-011: dunst <1.9 no soporta Wayland puro)
        _contenido = _leer_config("mako/config")
        if _contenido:
            self._escribir(f"{home}/.config/mako/config", _contenido)

        # rofi config
        _contenido = _leer_config("rofi/config.rasi")
        if _contenido:
            self._escribir(f"{home}/.config/rofi/config.rasi", _contenido)

        # powermenu
        _contenido = _leer_config("rofi/powermenu.sh")
        if _contenido:
            self._escribir(f"{home}/.config/rofi/scripts/powermenu.sh", _contenido)
        try:
            (MOUNT_ROOT / f"{home}/.config/rofi/scripts/powermenu.sh").chmod(0o755)
        except OSError as e:
            # Sin permisos de ejecución el powermenu de rofi fallará en el primer uso
            self._log(f"[WARN] chmod powermenu.sh falló: {e}", "warn")

        # kitty
        _contenido = _leer_config("kitty/kitty.conf")
        if _contenido:
            self._escribir(f"{home}/.config/kitty/kitty.conf", _contenido)

        # SDDM config
        self._escribir("etc/sddm.conf.d/hyprland.conf", """\
[Theme]
Current=avalos

[Wayland]
EnableHiDPI=true

[General]
HaltCommand=/usr/bin/systemctl poweroff
RebootCommand=/usr/bin/systemctl reboot
""")

        # Sesión Hyprland para SDDM
        self._escribir("usr/share/wayland-sessions/hyprland.desktop", """\
[Desktop Entry]
Name=Hyprland
Comment=An intelligent dynamic tiling Wayland compositor
Exec=Hyprland
Type=Application
""")

        # GTK theming
        for gtk_ver in ("gtk-3.0", "gtk-4.0"):
            self._escribir(f"{home}/.config/{gtk_ver}/settings.ini", """\
[Settings]
gtk-theme-name = Adwaita-dark
gtk-icon-theme-name = Papirus-Dark
gtk-font-name = JetBrainsMono Nerd Font 11
gtk-cursor-theme-name = capitaine-cursors-dark
gtk-cursor-theme-size = 24
gtk-application-prefer-dark-theme = true
""")

        # .bashrc extras
        bashrc_extra = """\

# ── AvalOS / Wayland ────────────────────────────────
export QT_QPA_PLATFORM=wayland
export MOZ_ENABLE_WAYLAND=1
export ELECTRON_OZONE_PLATFORM_HINT=auto
export XDG_SESSION_TYPE=wayland
"""
        bashrc_path = MOUNT_ROOT / f"{home}/.bashrc"
        try:
            existing = bashrc_path.read_text(encoding="utf-8") if bashrc_path.exists() else ""
            bashrc_path.write_text(existing + bashrc_extra, encoding="utf-8")
        except OSError as e:
            self._log(f"[WARN] .bashrc: {e}", "warn")

        # fastfetch config — claves traducidas al idioma elegido en el wizard
        _contenido = _leer_config("fastfetch/config.jsonc")
        if _contenido:
            try:
                from translations import TRANSLATIONS as _TR
                _tr = _TR.get(self._lang, _TR["en"])
                # Las claves en config.jsonc del repo están en inglés (baseline).
                # Mapeamos inglés → traducción del idioma elegido.
                _ff_keys = {
                    '" OS"':              f'"{_tr.get("ff-os",     " OS")}"',
                    '"\\uf0e4 Host"':     f'"{_tr.get("ff-host",   "\\uf0e4 Host")}"',
                    '" Kernel"':          f'"{_tr.get("ff-kernel",  " Kernel")}"',
                    '"\\uf55f Uptime"':   f'"{_tr.get("ff-uptime",  "\\uf55f Uptime")}"',
                    '"\\uf439 Packages"': f'"{_tr.get("ff-packages","\\uf439 Packages")}"',
                    '"\\uf879 Resolution"':f'"{_tr.get("ff-display","\\uf879 Resolution")}"',
                    '"\\uf4cb Disk"':     f'"{_tr.get("ff-disk",    "\\uf4cb Disk")}"',
                    '"\\uf55b RAM"':      f'"{_tr.get("ff-ram",     "\\uf55b RAM")}"',
                }
                for _old_k, _new_k in _ff_keys.items():
                    _contenido = _contenido.replace(_old_k, _new_k)
            except ImportError:
                pass  # translations.py no disponible — usar config tal cual
            self._escribir(f"{home}/.config/fastfetch/config.jsonc", _contenido)

        # Logo ASCII de fastfetch — copiar del live ISO al sistema instalado.
        # El live tiene /etc/fastfetch/avalos.txt generado por build-iso.yml;
        # sin copiarlo aquí, el sistema instalado mostraría el logo genérico de Arch.
        _src_logo = Path("/etc/fastfetch/avalos.txt")
        _dst_logo = MOUNT_ROOT / "etc" / "fastfetch" / "avalos.txt"
        _dst_logo.parent.mkdir(parents=True, exist_ok=True)
        if _src_logo.exists():
            import shutil as _shutil
            _shutil.copy2(_src_logo, _dst_logo)
            self._log("  ✓ /etc/fastfetch/avalos.txt copiado al sistema instalado")
        else:
            self._log("  [WARN] avalos.txt no encontrado en el live — fastfetch usará logo genérico", "warn")

        # Permisos
        self._chown_r(f"/home/{usuario}", usuario)

        # reflector timer
        ref_conf = MOUNT_ROOT / "etc" / "xdg" / "reflector" / "reflector.conf"
        ref_conf.parent.mkdir(parents=True, exist_ok=True)
        ref_conf.write_text("--country US,MX,GT\n--latest 10\n--sort rate\n--protocol https\n")
        self._run_chroot(["systemctl", "enable", "reflector.timer"])

        # linger service (PipeWire user services sin login interactivo)
        linger = MOUNT_ROOT / "etc/systemd/system/avalos-enable-linger.service"
        linger.parent.mkdir(parents=True, exist_ok=True)
        linger.write_text(f"""\
[Unit]
Description=Enable linger for {usuario} (PipeWire user services)
After=systemd-logind.service
ConditionPathExists=!/var/lib/systemd/linger/{usuario}

[Service]
Type=oneshot
ExecStart=/usr/bin/loginctl enable-linger {usuario}
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
""")
        self._run_chroot(["systemctl", "enable", "avalos-enable-linger.service"])
        self._log("  Hyprland configurado correctamente.", "ok")

    # ═════════════════════════════════════════════════════════════════════════
    #  FLUJO PRINCIPAL DE INSTALACIÓN
    # ═════════════════════════════════════════════════════════════════════════

    def _run_instalacion(self):
        self._instalando = True
        self._jsc("pyStartTimer")

        # Si es un reintento, _config_lista ya está set (la config no cambia).
        # Solo esperamos si todavía no se ha recibido la config del wizard.
        if not self._config_lista.is_set():
            if not self._config_lista.wait(timeout=600):
                self._log("[ERROR] Tiempo de espera agotado (10 min). Reinicia el instalador.", "err")
                self._jsc("pyErrorPaso", "Tiempo de espera agotado. Cierra y vuelve a abrir el instalador.")
                self._instalando = False
                return
        if self._abortado:
            self._instalando = False
            return

        usuario  = self._username
        passw    = self._password
        hostname = self._hostname
        timezone = self._timezone

        self._info("user", usuario, "ok")
        self._info("modo", "USB (noatime)" if self._modo_usb else "Disco (ext4)", "ok")
        _bl_labels = {"grub": "GRUB", "sd-boot": "systemd-boot", "refind": "rEFInd", "none": "Omitido"}
        self._info("grub", _bl_labels.get(self._bootloader, "GRUB"),
                   "ok" if self._bootloader != "none" else "warn")

        PASOS_IDS = [
            "uefi","net","tools","part","format","mount","mirrors",
            "pacstrap","fstab","config","grub","services","user",
            "aur","hyprland","umount",
        ]
        total = len(PASOS_IDS); paso = 0

        def avanzar():
            nonlocal paso; paso += 1
            self._progress(int(paso / total * 100))

        try:
            # ── PASO 0: Detectar discos + hardware ───────────────────────────
            self._label("detectando hardware…")
            self._status("Detectando discos y hardware…")
            discos    = listar_discos()
            disponibles = [d for d in discos if not d["es_arranque"]]
            disco_boot  = next((d for d in discos if d["es_arranque"]), None)

            # Detección inteligente de CPU y GPU
            cpu_arch = detectar_cpu_arch_level()
            gpu_info = detectar_gpu()
            _es_v3 = cpu_arch in ("x86-64-v3", "x86-64-v4")
            _kernel_display = "linux-avalos" if _es_v3 else "linux-avalos-compat"
            self._log(
                f"\nCPU arch: {cpu_arch} | GPU: {gpu_info['vendor'].upper()} ({gpu_info['model']})\n"
                f"Kernel seleccionado: {_kernel_display}",
                "ok"
            )

            # Mostrar info de hardware en el panel
            self._info("ucode", detectar_microcode(), "ok")
            self._jsc("pyInfo", "dest",
                      f"CPU: {cpu_arch} → {_kernel_display} · GPU: {gpu_info['vendor'].upper()}", "ok")

            if not disponibles:
                self._jsc("pyErrorFatal",
                          "No hay ningún disco disponible.\n"
                          f"El único disco ({disco_boot['name'] if disco_boot else '?'}) "
                          "es el disco de arranque (el live USB).")
                return

            # Usar disco elegido en wizard; si no se pasó, usar el primero disponible
            dev_name = self._disco_destino or disponibles[0]["name"]
            disco    = next((d for d in discos if d["name"] == dev_name), disponibles[0])
            dev_name = disco["name"]

            if disco["es_arranque"]:
                self._jsc("pyErrorFatal",
                          f"El disco /dev/{dev_name} es el disco de arranque actual.\n"
                          "Selecciona un disco diferente.")
                return

            size_gb = disco["size_b"] / 1e9
            if size_gb < MIN_DISK_GB:
                self._jsc("pyErrorFatal",
                          f"El disco /dev/{dev_name} tiene solo {size_gb:.1f} GB.\n"
                          f"AvalOS necesita al menos {MIN_DISK_GB} GB para instalarse correctamente.")
                return

            dev = f"/dev/{dev_name}"
            disco_tipo = detectar_tipo_disco_destino(dev_name)
            self._info("dest", f"{dev} ({disco['size_human']} · {disco_tipo.upper()} · {disco['model']})", "ok")
            self._log(f"\nDisco destino: {dev} ({disco['size_human']} · {disco_tipo.upper()})", "ok")

            # ── PASO 1: UEFI ─────────────────────────────────────────────────
            self._step("uefi", "active")
            uefi = es_uefi()
            ucode = detectar_microcode()
            self._info("ucode", ucode, "ok")
            # Nota: se pasa None como estado de red para indicar "aún verificando"
            # pyBadges en JS recibe null → muestra el badge en estado "···" (neutro)
            self._jsc("pyBadges", None, uefi)
            self._step("uefi", "done", "UEFI" if uefi else "BIOS Legacy")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 2: Internet ─────────────────────────────────────────────
            self._step("net", "active")
            self._status("Verificando internet…")
            net_ok = verificar_internet()
            self._jsc("pyBadges", net_ok, uefi)
            if not net_ok:
                self._step("net", "error", "Sin conexión")
                self._jsc("pyErrorPaso",
                          "No hay conexión a internet.\n"
                          "pacstrap necesita descargar paquetes. Verifica tu red.")
                return
            self._step("net", "done", "Conectado")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 3: Herramientas ─────────────────────────────────────────
            self._step("tools", "active")
            herramientas = verificar_herramientas()
            faltantes = [h for h, ok in herramientas.items() if not ok]
            if faltantes:
                self._log(f"[WARN] Faltan: {', '.join(faltantes)} — intentando instalar…", "warn")
                self._run_cmd(["pacman", "-Sy", "--noconfirm", "--needed"] + faltantes, timeout=120)
            self._step("tools", "done")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 4: Particionar ──────────────────────────────────────────
            self._step("part", "active")
            self._status(f"Particionando {dev}…")
            self._log(f"\n── Particionando {dev} ──\n", "step")

            # Countdown 10s — BUG-009 FIX: Python controla el tiempo; JS solo muestra la UI.
            # Así la acción destructiva NUNCA ocurre antes de que el contador llegue a 0.
            self._jsc("pyIniciarCountdown", dev, disco["model"], disco["size_human"])
            for i in range(10, 0, -1):
                if self._abortado:
                    self._jsc("pyCerrarCountdown")
                    self._limpiar_montajes(); return
                self._jsc("pyActualizarCountdown", i - 1)  # JS solo actualiza el número
                time.sleep(1)
            self._jsc("pyCerrarCountdown")

            if self._abortado: self._limpiar_montajes(); return

            # Verificar que ninguna partición del disco destino está montada
            # (más allá del check de es_arranque, que solo detecta el boot disk)
            self._log("  Verificando que el disco destino no tiene particiones montadas…", "info")
            with open("/proc/mounts") as _mf:
                _proc_mounts = _mf.read()
            _dev_base = dev_name  # ej. "sdb", "nvme1n1"
            _mounted = []
            for _line in _proc_mounts.splitlines():
                if not _line.strip():
                    continue
                _parts = _line.split()
                _src = _parts[0].removeprefix("/dev/")
                # El dispositivo pertenece al disco si su nombre empieza con dev_base
                # y el siguiente carácter es un dígito o 'p' (partición), no otra letra
                if _src.startswith(_dev_base) and _src != _dev_base:
                    _suffix = _src[len(_dev_base):]
                    if _suffix and (_suffix[0].isdigit() or _suffix[0] == 'p'):
                        if _parts[0] != dev:
                            _mounted.append(_parts[1])
            if _mounted:
                _puntos = ", ".join(_mounted)
                self._jsc("pyErrorFatal",
                          f"El disco {dev} tiene particiones montadas en: {_puntos}.\n"
                          "Desmóntalas antes de continuar.")
                return
            self._log(f"  {dev} no tiene particiones montadas ✓", "ok")

            # Borrar tabla y crear particiones
            rc_wipe, _ = self._run_cmd(["wipefs", "-a", dev])
            if rc_wipe != 0:
                self._step("part", "error")
                self._jsc("pyErrorPaso",
                          f"wipefs falló en {dev}. El disco podría estar en uso.\n"
                          "Desmonta todas sus particiones y vuelve a intentarlo.")
                self._limpiar_montajes(); return

            if uefi:
                # GPT: 512MB EFI + resto root
                rc, _ = self._run_cmd([
                    "parted", "-s", dev,
                    "mklabel", "gpt",
                    "mkpart", "ESP", "fat32", "1MiB", "513MiB",
                    "set", "1", "esp", "on",
                    "mkpart", "root", "ext4", "513MiB", "100%",
                ])
                dev_efi  = dev + ("p1" if "nvme" in dev_name or "mmcblk" in dev_name else "1")
                dev_root = dev + ("p2" if "nvme" in dev_name or "mmcblk" in dev_name else "2")
            else:
                # MBR: 1MB BIOS boot + resto root
                rc, _ = self._run_cmd([
                    "parted", "-s", dev,
                    "mklabel", "msdos",
                    "mkpart", "primary", "ext4", "1MiB", "100%",
                    "set", "1", "boot", "on",
                ])
                dev_root = dev + ("p1" if "nvme" in dev_name or "mmcblk" in dev_name else "1")
                dev_efi  = ""

            if rc != 0:
                self._step("part", "error")
                self._jsc("pyErrorPaso", f"parted falló en {dev}. Revisa el log.")
                self._limpiar_montajes(); return

            # Esperar a que udev registre los nuevos nodos de bloque
            try:
                subprocess.run(["udevadm", "settle", "--timeout=5"], check=False)
            except Exception:
                time.sleep(2)  # fallback si udevadm no está disponible
            self._step("part", "done",
                       "GPT: EFI (512MB) + root" if uefi else "MBR: root (100%)")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 5: Formatear ────────────────────────────────────────────
            self._step("format", "active")
            self._status("Formateando particiones…")
            self._log("\n── Formateando ──\n", "step")

            if uefi:
                rc, _ = self._run_cmd(["mkfs.fat", "-F32", dev_efi])
                if rc != 0:
                    self._step("format", "error")
                    self._jsc("pyErrorPaso", f"mkfs.fat falló en {dev_efi}")
                    self._limpiar_montajes(); return

            if self._modo_usb:
                rc, _ = self._run_cmd(["mkfs.ext4", "-O", "^has_journal", "-F", dev_root])
            else:
                rc, _ = self._run_cmd(["mkfs.ext4", "-F", dev_root])

            if rc != 0:
                self._step("format", "error")
                self._jsc("pyErrorPaso", f"mkfs.ext4 falló en {dev_root}")
                self._limpiar_montajes(); return

            if uefi and self._modo_usb:
                _fmt_label = "FAT32 + ext4 sin journal (USB)"
            elif uefi:
                _fmt_label = "FAT32 + ext4"
            else:
                _fmt_label = "ext4 sin journal (USB)" if self._modo_usb else "ext4"
            self._step("format", "done", _fmt_label)
            # Segundo settle: esperar que el kernel actualice los nodos de bloque
            # después del formateo antes de intentar montar
            try:
                subprocess.run(["udevadm", "settle", "--timeout=5"], check=False)
            except Exception:
                time.sleep(1)
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 6: Montar ───────────────────────────────────────────────
            self._step("mount", "active")
            MOUNT_ROOT.mkdir(parents=True, exist_ok=True)
            rc, _ = self._run_cmd(["mount", dev_root, str(MOUNT_ROOT)])
            if rc != 0:
                self._step("mount", "error")
                self._jsc("pyErrorPaso", f"Error montando {dev_root}")
                self._limpiar_montajes(); return

            if uefi:
                MOUNT_EFI.mkdir(parents=True, exist_ok=True)
                rc, _ = self._run_cmd(["mount", dev_efi, str(MOUNT_EFI)])
                if rc != 0:
                    self._step("mount", "error")
                    self._jsc("pyErrorPaso", f"Error montando {dev_efi} en EFI")
                    self._limpiar_montajes(); return

            self._step("mount", "done")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 7: Mirrors ──────────────────────────────────────────────
            self._step("mirrors", "active")
            self._status("Optimizando mirrors con reflector…")
            self._log("\n── Optimizando mirrors ──\n", "step")
            self._run_cmd(["pacman", "-Sy", "--noconfirm", "--needed", "reflector"], timeout=120)
            rc, _ = self._run_cmd([
                "reflector", "--country", "US,MX,GT",
                "--latest", "10", "--sort", "rate",
                "--protocol", "https", "--save", "/etc/pacman.d/mirrorlist",
            ], timeout=120)
            if rc == 0:
                self._step("mirrors", "done", "Mirrors optimizados")
            else:
                self._step("mirrors", "skip", "Mirrors por defecto")
                self._log("[WARN] reflector falló — usando mirrors por defecto.", "warn")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 8: pacstrap ─────────────────────────────────────────────
            self._step("pacstrap", "active")
            self._status("Instalando sistema base con pacstrap…")
            self._label("instalando sistema base…")
            self._log("\n── pacstrap ──\n", "step")

            pkgs = list(BASE_PKGS)
            if self._bootloader == 'sd-boot':
                # systemd-boot incluido en systemd; quitar grub y os-prober
                pkgs = [p for p in pkgs if p not in {"grub", "os-prober"}]
            elif self._bootloader == 'refind':
                # refind se instala desde AUR/repo; quitar grub y os-prober
                pkgs = [p for p in pkgs if p not in {"grub", "os-prober"}]
            elif self._bootloader == 'none':
                pkgs = [p for p in pkgs if p not in {"grub", "efibootmgr", "os-prober"}]

            # ── Selección dinámica del kernel según CPU + repo [avalos] ──────
            # cpu_arch viene de detectar_cpu_arch_level():
            #   x86-64-v3 / x86-64-v4 → linux-avalos      (compilado con -march=x86-64-v3)
            #   x86-64-v2 / x86-64    → linux-avalos-compat (compilado con -march=x86-64)
            #
            # Ejemplos de CPUs "compat":
            #   Intel Celeron N5100/N5095 (Jasper Lake, sin AVX2)
            #   Intel Celeron N4500/N4505 (Jasper Lake)
            #   Intel Pentium Silver N6005 (Jasper Lake)
            #   Intel Celeron J4125 (Gemini Lake Refresh)
            #   Hardware virtualizado sin extensiones AVX2 expuestas
            #   Cualquier CPU x86-64 de generación anterior a ~2013

            _es_v3_o_superior = cpu_arch in ("x86-64-v3", "x86-64-v4")
            _nombre_cpu_nivel = "v3/v4 (AVX2+)" if _es_v3_o_superior else "baseline (sin AVX2)"
            self._log(f"  CPU detectada: {cpu_arch} → nivel {_nombre_cpu_nivel}", "info")

            # Intentar resolver el kernel desde el repo [avalos]
            self._log("  Verificando disponibilidad de kernels en repo [avalos]…", "info")
            _kernel_pkg  = "linux"
            _headers_pkg = "linux-headers"

            # El paquete objetivo según CPU
            _target_kernel  = "linux-avalos"         if _es_v3_o_superior else "linux-avalos-compat"
            _target_headers = "linux-avalos-headers" if _es_v3_o_superior else "linux-avalos-compat-headers"

            try:
                _rc, _out = self._run_cmd(
                    ["pacman", "-Syi", "--noconfirm", _target_kernel],
                    timeout=20, log_cls="info"
                )
                if _rc == 0:
                    _kernel_pkg  = _target_kernel
                    _headers_pkg = _target_headers
                    self._log(f"  Kernel: {_kernel_pkg} ✓ (repo [avalos] disponible)", "ok")
                else:
                    # Fallback: intentar el otro variant si está disponible
                    _alt_kernel  = "linux-avalos-compat" if _es_v3_o_superior else "linux-avalos"
                    _alt_headers = "linux-avalos-compat-headers" if _es_v3_o_superior else "linux-avalos-headers"
                    _rc2, _ = self._run_cmd(
                        ["pacman", "-Syi", "--noconfirm", _alt_kernel],
                        timeout=20, log_cls="info"
                    )
                    if _rc2 == 0:
                        _kernel_pkg  = _alt_kernel
                        _headers_pkg = _alt_headers
                        if not _es_v3_o_superior:
                            # CPU sin AVX2 pero solo linux-avalos (v3) disponible — puede no arrancar
                            self._log(
                                f"  [WARN] {_target_kernel} no disponible. "
                                f"linux-avalos (v3) podría no funcionar en esta CPU ({cpu_arch}).",
                                "warn"
                            )
                        else:
                            # CPU v3+ pero solo linux-avalos-compat disponible — subóptimo pero funciona
                            self._log(
                                f"  [WARN] {_target_kernel} no disponible. "
                                f"Usando {_alt_kernel} (compat) en CPU {cpu_arch}.",
                                "warn"
                            )
                    else:
                        self._log(
                            f"  Kernel: linux ({_target_kernel} aún no publicado — fallback al kernel estándar)",
                            "warn"
                        )
            except Exception as _e:
                self._log(f"  Kernel: linux (error al consultar repo [avalos]: {_e})", "warn")

            pkgs += [_kernel_pkg, _headers_pkg]
            # ── Drivers GPU + entorno gráfico + gaming ───────────────────────
            # Si ucode es string vacío (CPU no reconocida), no incluir en pkgs:
            # pacstrap falla con error si recibe un nombre de paquete vacío.
            pkgs += gpu_info["pkgs"] + HYPRLAND_PKGS + GAMING_PKGS + ([ucode] if ucode else [])
            self._log(f"GPU detectada: {gpu_info['vendor'].upper()} → drivers: {', '.join(gpu_info['pkgs'][:3])}…", "info")
            self._log(f"Total: {len(pkgs)} paquetes ({', '.join(pkgs[:8])}… +{max(0, len(pkgs)-8)} más)", "info")

            rc, _ = self._run_cmd(
                ["pacstrap", "-c", str(MOUNT_ROOT)] + pkgs,
                timeout=3600, log_cls="info"
            )
            if rc != 0:
                self._step("pacstrap", "error")
                self._jsc("pyErrorPaso", "pacstrap falló. Verifica internet o el caché local.")
                self._limpiar_montajes(); return

            self._step("pacstrap", "done")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 9: fstab ────────────────────────────────────────────────
            self._step("fstab", "active")
            self._status("Generando fstab…")
            rc, fstab_out = self._run_cmd(["genfstab", "-U", str(MOUNT_ROOT)])
            if rc != 0 or not fstab_out.strip():
                self._step("fstab", "error")
                self._jsc("pyErrorPaso", "genfstab falló.")
                self._limpiar_montajes(); return

            if self._modo_usb:
                import re as _re
                # Reemplazar relatime por noatime en todas las líneas del fstab
                fstab_out = fstab_out.replace("relatime", "noatime")
                # Si una línea ext4 no tiene noatime, añadirlo — excluir líneas FAT/vfat (EFI)
                def _add_noatime(m):
                    opts = m.group(0)
                    if "noatime" not in opts and "vfat" not in opts.lower():
                        return opts.replace("defaults", "defaults,noatime", 1)
                    return opts
                fstab_out = _re.sub(r'(defaults[^\s]*)', _add_noatime, fstab_out)

            try:
                (MOUNT_ROOT / "etc" / "fstab").write_text(fstab_out + "\n")
            except OSError as e:
                self._step("fstab", "error")
                self._jsc("pyErrorPaso", f"No se pudo escribir fstab: {e}")
                self._limpiar_montajes(); return

            self._step("fstab", "done")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 10: Configurar sistema ───────────────────────────────────
            self._step("config", "active")
            self._status("Configurando locale, timezone, hostname…")
            self._log("\n── Configurando sistema ──\n", "step")

            self._run_chroot(["ln", "-sf", f"/usr/share/zoneinfo/{timezone}", "/etc/localtime"])
            self._run_chroot(["hwclock", "--systohc"])

            # Derivar locale_gen_entry y locale_conf desde self._locale
            # "es_SV.UTF-8" → "es_SV.UTF-8 UTF-8"  y  "LANG=es_SV.UTF-8"
            _loc     = self._locale       # ej. "es_SV.UTF-8"
            _loc_gen = f"{_loc} UTF-8"   # ej. "es_SV.UTF-8 UTF-8"
            _keymap  = self._keymap       # ej. "la-latin1"
            # Siempre incluir en_US.UTF-8 como locale de respaldo
            _loc_gen_extra = "en_US.UTF-8 UTF-8"
            # Si el locale elegido es chino, incluir también zh_CN.UTF-8
            _extra_locales = [_loc_gen, _loc_gen_extra]
            if _loc.startswith("zh_") and "zh_CN.UTF-8 UTF-8" not in _extra_locales:
                _extra_locales.append("zh_CN.UTF-8 UTF-8")

            locale_gen = MOUNT_ROOT / "etc" / "locale.gen"
            if locale_gen.exists():
                txt = locale_gen.read_text()
                for loc_entry in _extra_locales:
                    # Descomentamos tanto "#locale" como "# locale" (con o sin espacio)
                    txt = txt.replace(f"#{loc_entry}", loc_entry)
                    txt = txt.replace(f"# {loc_entry}", loc_entry)
                    # Añadir al final solo si realmente no quedó descomentado
                    if loc_entry not in txt:
                        txt += f"\n{loc_entry}\n"
                locale_gen.write_text(txt)
            else:
                # locale.gen no existe (no debería ocurrir tras pacstrap con glibc,
                # pero lo creamos para no dejar al sistema sin locales)
                self._log("[WARN] /etc/locale.gen no existe — creándolo desde cero", "warn")
                locale_gen.parent.mkdir(parents=True, exist_ok=True)
                locale_gen.write_text("\n".join(_extra_locales) + "\n")
            self._run_chroot(["locale-gen"])
            (MOUNT_ROOT / "etc" / "locale.conf").write_text(f"LANG={_loc}\n")
            (MOUNT_ROOT / "etc" / "vconsole.conf").write_text(f"KEYMAP={_keymap}\n")
            self._log(f"  Locale: {_loc} | Teclado: {_keymap}", "ok")
            (MOUNT_ROOT / "etc" / "hostname").write_text(hostname + "\n")
            (MOUNT_ROOT / "etc" / "hosts").write_text(
                f"127.0.0.1   localhost\n::1         localhost\n127.0.1.1   {hostname}.localdomain {hostname}\n"
            )

            rc_pw, out_pw = self._run_chroot_stdin(f"root:{passw}\n", ["chpasswd"])
            if rc_pw != 0:
                self._log(f"[ERROR] chpasswd root falló (rc={rc_pw}): {out_pw}", "err")
                self._limpiar_montajes()
                return
            self._run_chroot(["mkinitcpio", "-P"])

            self._step("config", "done", "locale · timezone · hostname · initramfs")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 11: GRUB ─────────────────────────────────────────────────
            self._step("grub", "active")
            if self._bootloader == 'none':
                self._step("grub", "skip", "Bootloader omitido por el usuario")
                self._log("[INFO] Sin bootloader — omitido por elección del usuario.", "warn")
                avanzar()

            elif self._bootloader == 'grub':
                self._status("Instalando GRUB…")
                self._log("\n── Instalando GRUB ──\n", "step")
                if uefi:
                    grub_cmd = ["grub-install", "--target=x86_64-efi",
                                "--efi-directory=/boot/efi", "--bootloader-id=GRUB"]
                    if GRUB_UEFI_REMOVABLE:
                        grub_cmd.append("--removable")
                    rc, _ = self._run_chroot(grub_cmd)
                else:
                    rc, _ = self._run_chroot(["grub-install", "--target=i386-pc", dev])

                if rc != 0:
                    self._step("grub", "error")
                    self._jsc("pyErrorPaso", "grub-install falló. Revisa el log.")
                    self._limpiar_montajes(); return

                # Activar os-prober para detectar otros OS en el menú
                gd_path = MOUNT_ROOT / "etc" / "default" / "grub"
                if gd_path.exists():
                    lines = [l for l in gd_path.read_text().splitlines()
                             if not l.strip().startswith("GRUB_DISABLE_OS_PROBER")]
                    lines.append("GRUB_DISABLE_OS_PROBER=false")
                    gd_path.write_text("\n".join(lines) + "\n")
                self._run_chroot(["grub-mkconfig", "-o", "/boot/grub/grub.cfg"])
                self._step("grub", "done", "GRUB instalado · os-prober activo")
                avanzar()


            elif self._bootloader == 'refind':
                # rEFInd: solo UEFI; detecta kernels automáticamente
                if not uefi:
                    self._step("grub", "error")
                    self._jsc("pyErrorPaso",
                              "rEFInd requiere UEFI. Esta máquina arranca en BIOS Legacy.\n"
                              "Elige GRUB en su lugar o reinicia el instalador.")
                    self._limpiar_montajes(); return

                self._status("Instalando rEFInd…")
                self._log("\n── Instalando rEFInd ──\n", "step")

                # Instalar el paquete refind
                rc, _ = self._run_chroot(["pacman", "-S", "--noconfirm", "--needed", "refind"])
                if rc != 0:
                    self._step("grub", "error")
                    self._jsc("pyErrorPaso",
                              "No se pudo instalar el paquete refind.\n"
                              "Verifica la conexión o añade un repo con el paquete.")
                    self._limpiar_montajes(); return

                # refind-install copia los archivos a la ESP y crea la entrada NVRAM
                rc, _ = self._run_chroot(["refind-install"])
                if rc != 0:
                    self._step("grub", "error")
                    self._jsc("pyErrorPaso", "refind-install falló. Revisa el log.")
                    self._limpiar_montajes(); return

                # Obtener UUID de la partición raíz para el refind_linux.conf
                rc_uuid, uuid_out, _ = _ejecutar(["blkid", "-s", "UUID", "-o", "value", dev_root])
                root_uuid = uuid_out.strip() if rc_uuid == 0 and uuid_out.strip() else ""
                root_opts = (f"root=UUID={root_uuid}" if root_uuid else f"root={dev_root}")

                # Detectar kernel instalado
                vmlinuz_files = glob.glob(str(MOUNT_ROOT / "boot" / "vmlinuz-*"))
                kernel_name = Path(vmlinuz_files[0]).name.replace("vmlinuz-", "") if vmlinuz_files else "linux"
                self._log(f"  Kernel detectado: {kernel_name}", "info")

                # Crear /boot/refind_linux.conf para que rEFInd sepa las opciones del kernel
                refind_conf = MOUNT_ROOT / "boot" / "refind_linux.conf"
                refind_conf.write_text(
                    f'"AvalOS (normal)"   "{root_opts} rw quiet splash loglevel=3"\n'
                    f'"AvalOS (verbose)"  "{root_opts} rw"\n'
                    f'"AvalOS (recovery)" "{root_opts} rw single"\n'
                )
                self._log("  /boot/refind_linux.conf creado.", "info")

                # Hook pacman para que rEFInd se actualice solo al actualizar el paquete
                hook_dir = MOUNT_ROOT / "etc" / "pacman.d" / "hooks"
                hook_dir.mkdir(parents=True, exist_ok=True)
                (hook_dir / "refind.hook").write_text(
                    "[Trigger]\n"
                    "Operation = Upgrade\n"
                    "Type = Package\n"
                    "Target = refind\n"
                    "\n"
                    "[Action]\n"
                    "Description = Actualizando rEFInd en la ESP…\n"
                    "When = PostTransaction\n"
                    "Exec = /usr/bin/refind-install\n"
                )

                self._step("grub", "done", f"rEFInd instalado · detecta {kernel_name} automáticamente")
                avanzar()
            elif self._bootloader == 'sd-boot':
                # systemd-boot: solo funciona en UEFI
                if not uefi:
                    self._step("grub", "error")
                    self._jsc("pyErrorPaso",
                              "systemd-boot requiere UEFI. Esta máquina arranca en BIOS Legacy.\n"
                              "Elige GRUB en su lugar o reinicia el instalador.")
                    self._limpiar_montajes(); return

                self._status("Instalando systemd-boot…")
                self._log("\n── Instalando systemd-boot ──\n", "step")

                # Instalar bootctl en la ESP montada en /boot/efi
                rc, _ = self._run_chroot(["bootctl", "install", "--esp-path=/boot/efi"])
                if rc != 0:
                    self._step("grub", "error")
                    self._jsc("pyErrorPaso", "bootctl install falló. Revisa el log.")
                    self._limpiar_montajes(); return

                # Detectar nombre del kernel instalado
                vmlinuz_files = glob.glob(str(MOUNT_ROOT / "boot" / "vmlinuz-*"))
                kernel_name = Path(vmlinuz_files[0]).name.replace("vmlinuz-", "") if vmlinuz_files else "linux"
                self._log(f"  Kernel detectado: {kernel_name}", "info")

                # Obtener UUID de la partición raíz
                rc_uuid, uuid_out, _ = _ejecutar(["blkid", "-s", "UUID", "-o", "value", dev_root])
                root_uuid = uuid_out.strip() if rc_uuid == 0 and uuid_out.strip() else ""

                # Copiar kernel e initramfs a la ESP
                # (systemd-boot lee archivos desde la ESP; con /boot/efi separado
                #  hay que copiarlos manualmente)
                esp_entries_dir = MOUNT_ROOT / "boot" / "efi" / "AvalOS"
                esp_entries_dir.mkdir(parents=True, exist_ok=True)

                _shutil = shutil   # shutil ya importado globalmente — alias local para claridad
                _shutil.copy2(MOUNT_ROOT / f"boot/vmlinuz-{kernel_name}",
                              esp_entries_dir / f"vmlinuz-{kernel_name}")
                initrd_src = MOUNT_ROOT / f"boot/initramfs-{kernel_name}.img"
                if initrd_src.exists():
                    _shutil.copy2(initrd_src, esp_entries_dir / f"initramfs-{kernel_name}.img")

                # Copiar imagen de microcode a la ESP
                _ucode_name = f"{ucode}.img"   # ucode ya detectado arriba: amd-ucode / intel-ucode
                _ucode_src  = MOUNT_ROOT / f"boot/{_ucode_name}"
                _ucode_copied = False
                if _ucode_src.exists():
                    _shutil.copy2(_ucode_src, esp_entries_dir / _ucode_name)
                    _ucode_copied = True
                    self._log(f"  microcode: {_ucode_name} copiado a ESP", "ok")
                else:
                    self._log(f"  [WARN] {_ucode_src} no encontrado — microcode omitido", "warn")

                # loader.conf
                loader_dir = MOUNT_ROOT / "boot" / "efi" / "loader"
                loader_dir.mkdir(parents=True, exist_ok=True)
                (loader_dir / "loader.conf").write_text(
                    "default  avalos.conf\n"
                    "timeout  3\n"
                    "console-mode auto\n"
                    "editor   no\n"
                )

                # entrada de arranque
                entries_dir = loader_dir / "entries"
                entries_dir.mkdir(parents=True, exist_ok=True)
                root_opts = (f"root=UUID={root_uuid}" if root_uuid else f"root={dev_root}")
                _ucode_initrd_line = (
                    f"initrd  /AvalOS/{_ucode_name}\n" if _ucode_copied else ""
                )
                (entries_dir / "avalos.conf").write_text(
                    f"title   AvalOS\n"
                    f"linux   /AvalOS/vmlinuz-{kernel_name}\n"
                    f"{_ucode_initrd_line}"
                    f"initrd  /AvalOS/initramfs-{kernel_name}.img\n"
                    f"options {root_opts} rw quiet splash loglevel=3\n"
                )

                # Hook para copiar kernel a ESP al hacer actualizaciones
                hook_dir = MOUNT_ROOT / "etc" / "pacman.d" / "hooks"
                hook_dir.mkdir(parents=True, exist_ok=True)
                (hook_dir / "95-systemd-boot.hook").write_text(
                    "[Trigger]\n"
                    "Type = Package\n"
                    f"Target = {kernel_name}\n"
                    "Operation = Install\n"
                    "Operation = Upgrade\n"
                    "\n"
                    "[Action]\n"
                    "Description = Updating systemd-boot kernel files\n"
                    "When = PostTransaction\n"
                    # BUG FIX: el hook original no copiaba el microcode a la ESP.
                    # Si ucode se actualiza junto con el kernel, la ESP queda con el
                    # microcode viejo hasta el próximo update manual. Se añade la copia
                    # con || true para que el hook no falle si ucode no existe.
                    f"Exec = /usr/bin/bash -c '"
                    f"cp /boot/vmlinuz-{kernel_name} /boot/efi/AvalOS/vmlinuz-{kernel_name}; "
                    f"cp /boot/initramfs-{kernel_name}.img /boot/efi/AvalOS/initramfs-{kernel_name}.img; "
                    f"[[ -n \"{ucode}\" ]] && [[ -f /boot/{ucode}.img ]] && cp /boot/{ucode}.img /boot/efi/AvalOS/{ucode}.img || true'\n"
                    "Depends = bash\n"
                )

                self._step("grub", "done", "systemd-boot instalado · entrada: avalos.conf")
                avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 12: Servicios ────────────────────────────────────────────
            self._step("services", "active")
            self._status("Habilitando servicios…")

            # Crear avalos-gpu-detect.service en el sistema instalado
            # (igual que en el live — detecta GPU antes de SDDM para que
            #  hyprland.conf pueda hacer `source` de gpu-env.conf ya escrito)
            _svc_dir = MOUNT_ROOT / "etc/systemd/system"
            _svc_dir.mkdir(parents=True, exist_ok=True)
            (_svc_dir / "avalos-gpu-detect.service").write_text(
                "[Unit]\n"
                "Description=AvalOS — GPU Environment Detection\n"
                "Documentation=https://github.com/jeffreysama/avalos\n"
                "Before=sddm.service display-manager.service\n"
                "After=systemd-udev-settle.service\n\n"
                "[Service]\n"
                "Type=oneshot\n"
                "ExecStart=/usr/local/bin/avalos-gpu-env\n"
                "RemainAfterExit=yes\n\n"
                "[Install]\n"
                "WantedBy=graphical.target\n"
            )
            _wants = _svc_dir / "graphical.target.wants"
            _wants.mkdir(exist_ok=True)
            _symlink = _wants / "avalos-gpu-detect.service"
            if not _symlink.exists():
                _symlink.symlink_to("/etc/systemd/system/avalos-gpu-detect.service")
            self._log("  avalos-gpu-detect.service creado y habilitado", "ok")

            for svc in ["NetworkManager", "bluetooth", "sddm", "lm_sensors"]:
                self._run_chroot(["systemctl", "enable", svc])
            self._run_chroot(["systemctl", "--global", "enable",
                              "pipewire", "pipewire-pulse", "wireplumber"])
            self._log("  [INFO] sensors-detect omitido — ejecutar manualmente tras el reinicio: sudo sensors-detect --auto", "warn")
            self._step("services", "done", "NetworkManager · bluetooth · sddm · pipewire · avalos-gpu-detect")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── OPTIMIZACIONES: ZRAM, oomd, BBR, IO scheduler ──────────────
            self._status("Aplicando optimizaciones del sistema…")
            self._log("\n── Optimizaciones del sistema ──\n", "step")
            gpu_info["_usuario"] = usuario
            # Pre-crear el directorio home del usuario para que _configurar_optimizaciones
            # pueda escribir gpu-env.conf aunque useradd aún no haya corrido.
            # Los permisos se corregirán con _chown_r en _configurar_hyprland.
            _home_pre = MOUNT_ROOT / f"home/{usuario}"
            _home_pre.mkdir(parents=True, exist_ok=True)
            self._configurar_optimizaciones(gpu_info, cpu_arch, disco_tipo)

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 13: Usuario ──────────────────────────────────────────────
            self._step("user", "active")
            self._status("Creando usuario…")
            self._log("\n── Creando usuario ──\n", "step")

            rc, _ = self._run_chroot([
                "useradd", "-m", "-G", "wheel,audio,video,storage,optical",
                "-s", "/bin/bash", usuario
            ])
            if rc != 0:
                self._step("user", "error")
                self._jsc("pyErrorPaso", f"useradd falló para '{usuario}'. Revisa el log.")
                self._limpiar_montajes(); return

            rc_pw2, out_pw2 = self._run_chroot_stdin(f"{usuario}:{passw}\n", ["chpasswd"])
            if rc_pw2 != 0:
                self._log(f"[ERROR] chpasswd '{usuario}' falló (rc={rc_pw2}): {out_pw2}", "err")
                self._limpiar_montajes()
                return

            # Sudo para wheel
            sudoers = MOUNT_ROOT / "etc" / "sudoers.d" / "wheel"
            sudoers.parent.mkdir(parents=True, exist_ok=True)
            sudoers.write_text("%wheel ALL=(ALL:ALL) ALL\n")
            sudoers.chmod(0o440)

            self._step("user", "done", f"Usuario '{usuario}' creado")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 14: AUR (yay) ────────────────────────────────────────────
            self._step("aur", "active")
            self._status("Instalando yay + paquetes AUR…")
            self._log("\n── yay + AUR ──\n", "step")

            sudoers_tmp = MOUNT_ROOT / "etc" / "sudoers.d" / "99-aur-build"
            try:
                sudoers_tmp.write_text(f"{usuario} ALL=(ALL:ALL) NOPASSWD: ALL\n")
            except OSError:
                sudoers_tmp = None

            yay_script = (
                "set -euo pipefail; "
                "TMPD=$(mktemp -d) && "
                "git clone --depth=1 https://aur.archlinux.org/yay.git \"$TMPD/yay_build\" && "
                "cd \"$TMPD/yay_build\" && "
                "makepkg -si --noconfirm --needed && "
                "rm -rf \"$TMPD\""
            )
            rc, _ = self._run_chroot(
                ["sudo", "-H", "-u", usuario, "bash", "-c", yay_script], timeout=600
            )
            if rc != 0:
                self._log("[WARN] yay no se instaló — paquetes AUR omitidos.", "warn")
                self._step("aur", "skip", "yay falló")
            else:
                all_aur = HYPRLAND_AUR_PKGS + GAMING_AUR_PKGS
                if all_aur:
                    rc_aur, _ = self._run_chroot(
                        ["sudo", "-H", "-u", usuario, "yay", "-S", "--noconfirm", "--needed"]
                        + all_aur, timeout=1800  # Proton-GE es grande, más tiempo
                    )
                    if rc_aur != 0:
                        self._log(
                            f"[WARN] Algunos paquetes AUR no se instalaron (rc={rc_aur}). "
                            "Puedes instalarlos manualmente con yay tras el reinicio.",
                            "warn"
                        )
                        self._step("aur", "done", f"{len(all_aur)} paquetes AUR (con advertencias)")
                    else:
                        self._step("aur", "done", f"{len(all_aur)} paquetes AUR")
                else:
                    self._step("aur", "done", "0 paquetes AUR")

                # ── Gaming post-install ───────────────────────────────────────
                # Agregar usuario al grupo gamemode
                self._run_chroot(["usermod", "-aG", "gamemode", usuario])

                # GameMode config
                gamemode_conf = (
                    "[general]\n"
                    "reaper_freq=5\n"
                    "defaultgov=performance\n"
                    "desiredgov=performance\n"
                    "softrealtime=auto\n"
                    "renice=-10\n\n"
                    "[gpu]\n"
                    "apply_gpu_optimisations=accept-responsibility\n"
                    "gpu_device=0\n"
                    "amd_performance_level=high\n\n"
                    "[filter]\n"
                    "whitelist=steam\nwhitelist=lutris\nwhitelist=heroic\n"
                )
                try:
                    gm_path = MOUNT_ROOT / "etc" / "gamemode.ini"
                    gm_path.write_text(gamemode_conf, encoding="utf-8")
                    self._log("  gamemode.ini configurado", "ok")
                except OSError as e:
                    self._log(f"[WARN] gamemode.ini: {e}", "warn")

                # MangoHUD config global
                _contenido_mango = _leer_config("mangohud/MangoHud.conf")
                if _contenido_mango:
                    mango_dir = MOUNT_ROOT / "etc" / "MangoHud"
                    mango_dir.mkdir(parents=True, exist_ok=True)
                    (mango_dir / "MangoHud.conf").write_text(_contenido_mango, encoding="utf-8")
                    self._log("  MangoHud.conf configurado", "ok")

                # Flatpak: instalar Heroic si no entró por AUR
                self._run_chroot(
                    ["sudo", "-H", "-u", usuario, "flatpak", "remote-add",
                     "--if-not-exists", "flathub",
                     "https://dl.flathub.org/repo/flathub.flatpakrepo"],
                    timeout=120
                )
                self._log("  Flathub configurado", "ok")

            if sudoers_tmp and sudoers_tmp.exists():
                try: sudoers_tmp.unlink()
                except OSError: pass

            avanzar()

            # ── PASO 15: Hyprland config ──────────────────────────────────────
            self._step("hyprland", "active")
            self._status("Configurando Hyprland + entorno Wayland…")
            self._label("configurando Hyprland…")
            self._log("\n── Configurando Hyprland + Wayland ──\n", "step")
            self._configurar_hyprland(usuario, gpu_info)
            self._step("hyprland", "done", "SDDM · Waybar · hyprland.conf · rofi · kitty")
            avanzar()

            if self._abortado: self._limpiar_montajes(); return

            # ── PASO 16: Desmontar ────────────────────────────────────────────
            self._step("umount", "active")
            self._status("Desmontando y finalizando…")
            self._log("\n── Desmontando todo ──\n", "step")
            self._limpiar_montajes()
            self._step("umount", "done")
            avanzar()

            # ── LISTO ─────────────────────────────────────────────────────────
            done_info = (
                f"<strong>Disco:</strong> {dev} ({disco['size_human']})<br>"
                f"<strong>Usuario:</strong> {usuario}<br>"
                f"<strong>Hostname:</strong> {hostname}<br>"
                f"<strong>Timezone:</strong> {timezone}<br>"
                f"<strong>Modo:</strong> {'USB (noatime)' if self._modo_usb else 'Disco (ext4)'}<br>"
                f"<strong>Bootloader:</strong> { {'grub':'GRUB','sd-boot':'systemd-boot','refind':'rEFInd','none':'Omitido'}.get(self._bootloader,'?') }<br>"
                f"<strong>DE/WM:</strong> Hyprland · Wayland · SDDM<br>"
                f"<strong>⚠ Contraseña:</strong> cambio requerido en el primer login"
            )
            self._jsc("pyInstalacionCompleta", done_info)
            self._label("✓ completado")
            self._log(
                f"\n╔══════════════════════════════════════════╗\n"
                f"║  ✓  AvalOS instalado correctamente       ║\n"
                f"║  Disco:    {dev} ({disco['size_human']}) ║\n"
                f"║  Usuario:  {usuario} ║\n"
                f"║  Hostname: {hostname} ║\n"
                f"║  Timezone: {timezone} ║\n"
                f"║  DE/WM:    Hyprland · Wayland · SDDM ║\n"
                f"╚══════════════════════════════════════════╝", "ok"
            )

        except Exception as e:
            import traceback  # noqa: PLC0415 — import lazy intencional en except crítico
            self._log(f"\n[EXCEPCIÓN] {e}\n{traceback.format_exc()}", "err")
            self._jsc("pyErrorPaso", f"Error inesperado: {e}")
            self._limpiar_montajes()
        finally:
            self._instalando = False
            # Garantizar que el sudoers NOPASSWD temporal nunca quede en el sistema
            # instalado, aunque haya ocurrido una excepción durante el paso AUR.
            _sudoers_guard = MOUNT_ROOT / "etc" / "sudoers.d" / "99-aur-build"
            if _sudoers_guard.exists():
                try:
                    _sudoers_guard.unlink()
                    self._log("  [cleanup] sudoers temporal eliminado", "ok")
                except OSError as _e:
                    self._log(f"  [WARN] No se pudo eliminar sudoers temporal: {_e}", "warn")
            self._jsc("pyStopTimer")


# ═══════════════════════════════════════════════════════════════════════════════
#  INYECTAR VARIABLES EN EL HTML (timezones, defaults)
# ═══════════════════════════════════════════════════════════════════════════════

def _build_html() -> str:
    # Inject logo base64 into the HTML placeholder
    tz_json       = json.dumps(TIMEZONES, ensure_ascii=False)
    default_tz    = json.dumps(DEFAULT_TIMEZONE)
    default_host  = json.dumps(DEFAULT_HOSTNAME)
    locales_json  = json.dumps(LOCALES, ensure_ascii=False)
    keymaps_json  = json.dumps(KEYMAPS, ensure_ascii=False)
    default_loc   = json.dumps(DEFAULT_LOCALE)
    default_km    = json.dumps(DEFAULT_KEYMAP)

    inject = (
        f"window._tzList = {tz_json};\n"
        f"window._defaultTZ = {default_tz};\n"
        f"window._defaultHostname = {default_host};\n"
        f"window._localeList = {locales_json};\n"
        f"window._keymapList = {keymaps_json};\n"
        f"window._defaultLocale = {default_loc};\n"
        f"window._defaultKeymap = {default_km};\n"
    )
    # Insertar justo antes del cierre </script> del bloque READY
    contenido = _HTML.replace("LOGO_PLACEHOLDER", _LOGO_B64)
    return contenido.replace(
        "window.addEventListener('pywebviewready'",
        inject + "window.addEventListener('pywebviewready'"
    )


# ═══════════════════════════════════════════════════════════════════════════════
#  ENTRY POINT — ejecutar directamente desde el live USB
# ═══════════════════════════════════════════════════════════════════════════════

if __name__ == "__main__":
    # Verificar que corre como root
    if os.geteuid() != 0:
        print("╔═══════════════════════════════════════════════════╗")
        print("║  AvalOS Installer necesita privilegios de root.   ║")
        print("╠═══════════════════════════════════════════════════╣")
        print("║  Ejecuta con:  sudo python avalos-install         ║")
        print("║  O como root:  python avalos-install              ║")
        print("╚═══════════════════════════════════════════════════╝")
        sys.exit(1)

    vent = VentanaInstalador()
    api  = InstaladorAPI(vent)

    html = _build_html()

    win = webview.create_window(
        title            = "AvalOS — Instalador",
        html             = html,
        js_api           = api,
        width            = 960,
        height           = 640,
        min_size         = (800, 540),
        resizable        = True,
        background_color = "#1a1b26",
    )
    vent.window = win
    win.events.closed += vent._on_close

    # Arrancar el hilo de instalación cuando el DOM esté listo
    def _on_loaded():
        # Lock para evitar race condition TOCTOU: pywebview puede disparar
        # el evento 'loaded' varias veces (recarga del DOM, SPA navigation).
        # _config_lista.clear() se hace DENTRO del lock para evitar la carrera
        # con iniciar_instalacion() que llama .set() desde otro hilo.
        with vent._lock:
            if vent._thread_started:
                return
            vent._thread_started = True
            vent._config_lista.clear()   # ← dentro del lock
        t = threading.Thread(target=vent._run_instalacion, daemon=True)
        t.start()

    win.events.loaded += _on_loaded

    # gui=None → auto-detect (GTK en Linux/Wayland, QtWebEngine como fallback)
    try:
        webview.start(debug=False)
    except Exception as e:
        print(f"ERROR al iniciar pywebview: {e}")
        print("Asegúrate de que webkit2gtk-4.1 esté instalado:")
        print("  pacman -S webkit2gtk-4.1 python-gobject")
        sys.exit(1)
